Here's the result of running `cat -n` on D:\UnityProjects\AiTest\Assets\Scripts\CustomFollower.cs:
 1	using UnityEngine;
 2	using PathBerserker2d;
 3	using System.Collections.Generic;
 4	
 5	[RequireComponent(typeof(NavAgent))]
 6	public class CustomFollower : MonoBehaviour
 7	{
 8	 [Header("Following")]
 9	 [SerializeField] public Transform target;
 10	 [SerializeField] private float closeEnoughRadius = 3.0f;
 11	 [SerializeField] private float travelStopRadius = 1.0f;
 12	 [SerializeField] private float updateFrequency = 0.3f;
 13	 [SerializeField] private float targetPredictionTime = 0.1f; // Предсказание движения цели
 14	 
 15	 [Header("Ally Avoidance")]
 16	 [SerializeField] private float allyDetectionDistance = 1.5f;
 17	 [SerializeField] private float avoidanceOffset = 2.0f;
 18	 [SerializeField] private float avoidanceCheckInterval = 0.3f;
 19	 [SerializeField] private float maxAvoidanceTime = 4f; // Максимальное время обхода
 20	 [SerializeField] private bool enableAvoidance = true;
 21	 
 22	 // Компоненты
 23	 private NavAgent navAgent;
 24	 private List<GameObject> teammates = new List<GameObject>();
 25	 
 26	 // Состояние
 27	 private float updateTimer = 0f;
 28	 private float checkTimer = 0f;
 29	 private float avoidanceTimer = 0f;
 30	 private bool isAvoiding = false;
 31	 private GameObject blockingAlly = null;
 32	 private Vector2 lastTargetPosition;
 33	 private int failedPathAttempts = 0;
 34	 
 35	 private void Awake()
 36	 {
 37	 navAgent = GetComponent<NavAgent>();
 38	 }
 39	 
 40	 private void Start()
 41	 {
 42	 // Определяем союзников из нашей команды
 43	 if (BotManager.Instance != null)
 44	 {
 45	 if (BotManager.Instance.IsInTeam1(gameObject))
 46	 teammates = BotManager.Instance.GetTeam1Bots();
 47	 else if (BotManager.Instance.IsInTeam2(gameObject))
 48	 teammates = BotManager.Instance.GetTeam2Bots();
 49	 }
 50	 
 51	 // Начальный путь к цели
 52	 if (target != null)
 53	 {
 54	 lastTargetPosition = target.position;
 55	 navAgent.PathTo(target.position);
 56	 }
 57	 
 58	 // Подписываемся на события
 59	 navAgent.OnReachedGoal += OnReachedGoal;
 60	 navAgent.OnFailedToFindPath += OnFailedToFindPath;
 61	 }
 62	 
 63	 private void OnDestroy()
 64	 {
 65	 // Отписываемся от событий
 66	 if (navAgent != null)
 67	 {
 68	 navAgent.OnReachedGoal -= OnReachedGoal;
 69	 navAgent.OnFailedToFindPath -= OnFailedToFindPath;
 70	 }
 71	 }
 72	 
 73	 private void OnReachedGoal(NavAgent agent)
 74	 {
 75	 // Сбрасываем состояние избегания
 76	 isAvoiding = false;
 77	 avoidanceTimer = 0f;
 78	 failedPathAttempts = 0;
 79	 }
 80	 
 81	 private void OnFailedToFindPath(NavAgent agent)
 82	 {
 83	 failedPathAttempts++;
 84	 
 85	 // Если много неудачных попыток, сбрасываем состояние избегания
 86	 if (failedPathAttempts >= 3)
 87	 {
 88	 isAvoiding = false;
 89	 avoidanceTimer = 0f;
 90	 }
 91	 }
 92	 
 93	 private void Update()
 94	 {
 95	 if (target == null || !navAgent.enabled)
 96	 return;
 97	 
 98	 // Обновление таймеров
 99	 updateTimer += Time.deltaTime;
 100	 checkTimer += Time.deltaTime;
 101	 
 102	 if (isAvoiding)
 103	 {
 104	 avoidanceTimer += Time.deltaTime;
 105	 
 106	 // Если обход длится слишком долго, принудительно возвращаемся к цели
 107	 if (avoidanceTimer > maxAvoidanceTime)
 108	 {
 109	 isAvoiding = false;
 110	 avoidanceTimer = 0f;
 111	 TryDirectPathToTarget();
 112	 }
 113	 }
 114	 
 115	 // Обновление пути к цели
 116	 if (updateTimer >= updateFrequency)
 117	 {
 118	 updateTimer = 0f;
 119	 UpdatePathToTarget();
 120	 }
 121	 
 122	 // Проверка на блокирующих союзников
 123	 if (checkTimer >= avoidanceCheckInterval && enableAvoidance && navAgent.IsFollowingAPath && !isAvoiding)
 124	 {
 125	 checkTimer = 0f;
 126	 CheckForBlockingAllies();
 127	 }
 128	 
 129	 //для проверки близости союзников
 130	 if (!isAvoiding && navAgent.IsIdle)
 131	 {
 132	 CheckForTooCloseAllies();
 133	 }
 134	 }
 135	 
 136	 private void UpdatePathToTarget()
 137	 {
 138	 if (target == null) return;
 139	 
 140	 Vector2 targetPos = target.position;
 141	 float distToTarget = Vector2.Distance(transform.position, targetPos);
 142	 
 143	 // Предсказываем движение цели
 144	 if (targetPredictionTime > 0 && Vector2.Distance(targetPos, lastTargetPosition) > 0.1f)
 145	 {
 146	 Vector2 targetVelocity = (targetPos - lastTargetPosition) / updateFrequency;
 147	 targetPos += targetVelocity * targetPredictionTime;
 148	 }
 149	 
 150	 // Обновляем позицию цели
 151	 lastTargetPosition = target.position;
 152	 
 153	 // ВАЖНОЕ ИЗМЕНЕНИЕ: Улучшенная логика остановки
 154	 if (distToTarget < travelStopRadius)
 155	 {
 156	 // Если мы слишком близко, останавливаемся
 157	 navAgent.Stop();
 158	 
 159	 // Если мы ОЧЕНЬ близко, активно отходим назад
 160	 if (distToTarget < travelStopRadius * 0.7f) 
 161	 {
 162	 Vector2 directionFromTarget = (Vector2)transform.position - targetPos;
 163	 directionFromTarget.Normalize();
 164	 
 165	 // Рассчитываем точку отступления
 166	 Vector2 retreatPoint = targetPos + directionFromTarget * (travelStopRadius * 1.2f);
 167	 navAgent.PathTo(retreatPoint);
 168	 
 169	 Debug.Log($"Бот {name} отступает от цели {target.name}, расстояние: {distToTarget}");
 170	 }
 171	 return;
 172	 }
 173	 
 174	 // Если мы находимся в "зоне комфорта" (между travelStopRadius и closeEnoughRadius)
 175	 // мы не обновляем путь, чтобы предотвратить постоянные перемещения
 176	 if (distToTarget >= travelStopRadius && distToTarget <= closeEnoughRadius)
 177	 {
 178	 // Находимся на нормальном расстоянии, ничего не делаем
 179	 return;
 180	 }
 181	 
 182	 // Если не в режиме избегания и слишком далеко, следуем к цели
 183	 if (!isAvoiding && distToTarget > closeEnoughRadius)
 184	 {
 185	 navAgent.UpdatePath(targetPos);
 186	 }
 187	 }
 188	 
 189	 private void TryDirectPathToTarget()
 190	 {
 191	 if (target != null)
 192	 {
 193	 navAgent.UpdatePath(target.position);
 194	 Debug.Log($"Бот {name} возвращается напрямую к цели {target.name}");
 195	 }
 196	 }
 197	 
 198	 private void CheckForBlockingAllies()
 199	 {
 200	 if (target == null) return;
 201	 
 202	 // Находим блокирующего союзника
 203	 GameObject ally = FindBlockingTeammate();
 204	 
 205	 if (ally != null)
 206	 {
 207	 // Союзник найден, переходим в режим обхода
 208	 blockingAlly = ally;
 209	 Vector2 avoidancePoint = CalculateAvoidancePoint(blockingAlly.transform.position);
 210	 
 211	 isAvoiding = true;
 212	 avoidanceTimer = 0f;
 213	 navAgent.UpdatePath(avoidancePoint);
 214	 
 215	 Debug.Log($"Бот {name} избегает {blockingAlly.name}");
 216	 }
 217	 }
 218	 
 219	 private GameObject FindBlockingTeammate()
 220	 {
 221	 if (teammates.Count == 0 || target == null) 
 222	 return null;
 223	 
 224	 Vector2 myPosition = transform.position;
 225	 Vector2 goalPosition = target.position;
 226	 Vector2 directionToGoal = goalPosition - myPosition;
 227	 float distanceToGoal = directionToGoal.magnitude;
 228	 
 229	 // Если цель очень близко, не нужно избегать
 230	 //if (distanceToGoal < travelStopRadius * 2f) 
 231	 // return null;
 232	 
 233	 directionToGoal /= distanceToGoal; // Нормализация
 234	 
 235	 foreach (GameObject ally in teammates)
 236	 {
 237	 if (ally == null || ally == gameObject) 
 238	 continue;
 239	 
 240	 Vector2 allyPosition = ally.transform.position;
 241	 
 242	 // Расстояние до союзника
 243	 float distanceToAlly = Vector2.Distance(myPosition, allyPosition);
 244	 
 245	 // Если союзник слишком далеко, пропускаем
 246	 if (distanceToAlly > allyDetectionDistance * 2f)
 247	 continue;
 248	 
 249	 // Вычисляем проекцию союзника на линию пути
 250	 float projection = Vector2.Dot(allyPosition - myPosition, directionToGoal);
 251	 
 252	 // Игнорируем союзников позади нас или за целью
 253	 //if (projection <= 0 || projection >= distanceToGoal * 0.95f) 
 254	 // continue;
 255	 
 256	 // Вычисляем точку проекции на линии пути
 257	 Vector2 projectedPoint = myPosition + directionToGoal * projection;
 258	 
 259	 // Расстояние от союзника до линии пути
 260	 float distanceFromPath = Vector2.Distance(allyPosition, projectedPoint);
 261	 
 262	 // Если союзник достаточно близко к пути
 263	 if (distanceFromPath < allyDetectionDistance)
 264	 {
 265	 return ally;
 266	 }
 267	 }
 268	 
 269	 return null;
 270	 }
 271	 
 272	 private Vector2 CalculateAvoidancePoint(Vector2 allyPosition)
 273	 {
 274	 if (target == null)
 275	 return transform.position;
 276	 
 277	 Vector2 myPosition = transform.position;
 278	 Vector2 targetPosition = target.position;
 279	 
 280	 // Направление к цели
 281	 Vector2 dirToTarget = (targetPosition - myPosition).normalized;
 282	 
 283	 // Расстояние между мной и целью
 284	 float distanceToTarget = Vector2.Distance(myPosition, targetPosition);
 285	 
 286	 // Перпендикулярный вектор для обхода
 287	 Vector2 perpendicularDir = new Vector2(-dirToTarget.y, dirToTarget.x);
 288	 
 289	 // Определяем, с какой стороны обходить
 290	 Vector2 toAlly = allyPosition - myPosition;
 291	 if (Vector2.Dot(toAlly, perpendicularDir) < 0)
 292	 perpendicularDir = -perpendicularDir;
 293	 
 294	 // Точка обхода: около 45 градусов от прямого направления
 295	 // Создаем гибрид между боковым и вперед направлениями
 296	 Vector2 avoidDir = (dirToTarget + perpendicularDir).normalized;
 297	 
 298	 // Рассчитываем точку обхода на расстоянии, пропорциональном от союзника до цели
 299	 float avoidDistance = Mathf.Min(avoidanceOffset, distanceToTarget * 0.5f);
 300	 Vector2 avoidancePoint = allyPosition + avoidDir * avoidDistance;
 301	 
 302	 return avoidancePoint;
 303	 }
 304	 
 305	 // Метод для проверки и отталкивания от близких союзников
 306	 private void CheckForTooCloseAllies()
 307	 {
 308	 if (teammates == null || teammates.Count == 0) 
 309	 return;
 310	 
 311	 Vector2 myPosition = transform.position;
 312	 GameObject tooCloseAlly = null;
 313	 float closestDistance = float.MaxValue;
 314	 
 315	 // Ищем ближайшего союзника, который стоит слишком близко
 316	 foreach (GameObject ally in teammates)
 317	 {
 318	 if (ally == null || ally == gameObject) 
 319	 continue;
 320	 
 321	 float distance = Vector2.Distance(myPosition, ally.transform.position);
 322	 
 323	 // Если союзник ближе минимального расстояния
 324	 if (distance < allyDetectionDistance * 0.7f && distance < closestDistance)
 325	 {
 326	 tooCloseAlly = ally;
 327	 closestDistance = distance;
 328	 }
 329	 }
 330	 
 331	 // Если нашли слишком близкого союзника
 332	 if (tooCloseAlly != null)
 333	 {
 334	 Vector2 directionFromAlly = myPosition - (Vector2)tooCloseAlly.transform.position;
 335	 
 336	 // Если направление нулевое (находимся в той же точке), создаем случайное направление
 337	 if (directionFromAlly.magnitude < 0.1f)
 338	 {
 339	 directionFromAlly = new Vector2(Random.Range(-1f, 1f), Random.Range(-1f, 1f));
 340	 }
 341	 
 342	 directionFromAlly.Normalize();
 343	 
 344	 // Вычисляем точку отхода
 345	 Vector2 retreatPoint = myPosition + directionFromAlly * allyDetectionDistance * 1.5f;
 346	 
 347	 // Создаем путь отхода
 348	 navAgent.PathTo(retreatPoint);
 349	 Debug.Log($"Бот {name} отходит от слишком близкого союзника {tooCloseAlly.name}");
 350	 }
 351	 }
 352	 
 353	 // Методы настройки
 354	 public void SetFollowingParameters(float closeEnough, float stopRadius, float updateRate, float predictionTime)
 355	 {
 356	 closeEnoughRadius = closeEnough;
 357	 travelStopRadius = stopRadius;
 358	 updateFrequency = updateRate;
 359	 targetPredictionTime = predictionTime;
 360	 }
 361	 
 362	 public void SetAvoidanceParameters(float detection, float offset, float interval, float maxAvoidTime)
 363	 {
 364	 allyDetectionDistance = detection;
 365	 avoidanceOffset = offset;
 366	 avoidanceCheckInterval = interval;
 367	 maxAvoidanceTime = maxAvoidTime;
 368	 }
 369	 
 370	 private void OnDrawGizmos()
 371	 {
 372	 if (!Application.isPlaying) return;
 373	 
 374	 // Радиус обнаружения союзников
 375	 Gizmos.color = enableAvoidance ? Color.cyan : Color.gray;
 376	 Gizmos.DrawWireSphere(transform.position, allyDetectionDistance);
 377	 
 378	 // Дистанция остановки
 379	 if (target != null)
 380	 {
 381	 Gizmos.color = Color.green;
 382	 Gizmos.DrawWireSphere(target.position, travelStopRadius);
 383	 }
 384	 
 385	 // Отображаем блокирующего союзника и путь обхода
 386	 if (isAvoiding && blockingAlly != null)
 387	 {
 388	 Gizmos.color = Color.red;
 389	 Gizmos.DrawLine(transform.position, blockingAlly.transform.position);
 390	 
 391	 // Точка обхода
 392	 if (navAgent.PathGoal.HasValue)
 393	 {
 394	 Gizmos.color = Color.yellow;
 395	 Gizmos.DrawWireSphere(navAgent.PathGoal.Value, 0.3f);
 396	 Gizmos.DrawLine(transform.position, navAgent.PathGoal.Value);
 397	 }
 398	 }
 399	 }
 400	}
