 1	using System.Collections.Generic;
 2	using UnityEngine;
 3	using PathBerserker2d;
 4	
 5	public class BotManager : MonoBehaviour
 6	{
 7	 [System.Serializable]
 8	 public class PathFollowingSettings
 9	 {
 10	 [Header("Path Following")]
 11	 public float closeEnoughRadius = 3.0f;
 12	 public float travelStopRadius = 1.0f;
 13	 public float updateFrequency = 0.3f;
 14	 public float targetPredictionTime = 0.1f;
 15	 }
 16	
 17	 [System.Serializable]
 18	 public class AvoidanceSettings
 19	 {
 20	 [Header("Ally Avoidance")]
 21	 public float allyDetectionDistance = 1.5f;
 22	 public float pathRecalculationInterval = 0.5f;
 23	 public float avoidanceOffset = 2.0f;
 24	 public float maxAvoidanceTime = 3.0f;
 25	 }
 26	
 27	 [System.Serializable]
 28	 public class TeamSettings
 29	 {
 30	 public Transform[] spawnPoints;
 31	 public int botCount = 4;
 32	 public Color teamColor = Color.white;
 33	 
 34	 [Header("Индивидуальные настройки команды (если используются)")]
 35	 public bool useTeamSpecificSettings = false;
 36	 [Tooltip("Настройки пути для этой команды (если useTeamSpecificSettings = true)")]
 37	 public PathFollowingSettings pathSettings = new PathFollowingSettings();
 38	 [Tooltip("Настройки избегания для этой команды (если useTeamSpecificSettings = true)")]
 39	 public AvoidanceSettings avoidanceSettings = new AvoidanceSettings();
