 282	 
 283	 // Расстояние между мной и целью
 284	 float distanceToTarget = Vector2.Distance(myPosition, targetPosition);
 285	 
 286	 // Перпендикулярный вектор для обхода
 287	 Vector2 perpendicularDir = new Vector2(-dirToTarget.y, dirToTarget.x);
 288	 
 289	 // Определяем, с какой стороны обходить
 290	 Vector2 toAlly = allyPosition - myPosition;
 291	 if (Vector2.Dot(toAlly, perpendicularDir) < 0)
 292	 perpendicularDir = -perpendicularDir;
