 305	 // Метод для проверки и отталкивания от близких союзников
 306	 private void CheckForTooCloseAllies()
 307	 {
 308	 if (teammates == null || teammates.Count == 0) 
 309	 return;
 310	 
 311	 Vector2 myPosition = transform.position;
 312	 GameObject tooCloseAlly = null;
 313	 float closestDistance = float.MaxValue;
 314	 
 315	 // Ищем ближайшего союзника, который стоит слишком близко
 316	 foreach (GameObject ally in teammates)
 317	 {
 318	 if (ally == null || ally == gameObject) 
 319	 continue;
 320	 
 321	 float distance = Vector2.Distance(myPosition, ally.transform.position);
 322	 
 323	 // Если союзник ближе минимального расстояния
 324	 if (distance < allyDetectionDistance * 0.7f && distance < closestDistance)
 325	 {
 326	 tooCloseAlly = ally;
 327	 closestDistance = distance;
 328	 }
 329	 }
 330	 
 331	 // Если нашли слишком близкого союзника
 332	 if (tooCloseAlly != null)
 333	 {
 334	 Vector2 directionFromAlly = myPosition - (Vector2)tooCloseAlly.transform.position;
 335	 
 336	 // Если направление нулевое (находимся в той же точке), создаем случайное направление
 337	 if (directionFromAlly.magnitude < 0.1f)
 338	 {
 339	 directionFromAlly = new Vector2(Random.Range(-1f, 1f), Random.Range(-1f, 1f));
 340	 }
 341	 
 342	 directionFromAlly.Normalize();
 343	 
 344	 // Вычисляем точку отхода
 345	 Vector2 retreatPoint = myPosition + directionFromAlly * allyDetectionDistance * 1.5f;
 346	 
 347	 // Создаем путь отхода
 348	 navAgent.PathTo(retreatPoint);
 349	 Debug.Log($"Бот {name} отходит от слишком близкого союзника {tooCloseAlly.name}");
 350	 }
 351	 }
