 5	/// <summary>
 6	/// Улучшенный компонент следования с интеграцией PathBerserker2d и избеганием союзников/врагов
 7	/// </summary>
 8	[RequireComponent(typeof(NavAgent))]
 9	public class CustomFollower : MonoBehaviour
 10	{
 11	 [Header("Target")]
 12	 public Transform target;
 13	
 14	 // Компоненты
 15	 private NavAgent navAgent;
 16	 private BotManager.PathFollowingSettings pathSettings;
 17	 private BotManager.AvoidanceSettings avoidanceSettings;
