 56	 /// <summary>
 57	 /// Инициализация настроек из BotManager
 58	 /// </summary>
 59	 private void InitializeFromBotManager()
 60	 {
 61	 if (BotManager.Instance == null)
 62	 {
 63	 Debug.LogError($"BotManager.Instance is null for {name}. Using default settings.");
 64	 return;
 65	 }
 66	
 67	 pathSettings = BotManager.Instance.GetPathSettings(gameObject);
 68	 avoidanceSettings = BotManager.Instance.GetAvoidanceSettings(gameObject);
 69	 }
 70	
 71	 /// <summary>
 72	 /// Кэширование списков команд для оптимизации
 73	 /// </summary>
 74	 private void CacheTeamLists()
 75	 {
 76	 if (BotManager.Instance == null) return;
 77	
 78	 teammates = BotManager.Instance.GetTeamBots(BotManager.Instance.GetBotTeamID(gameObject));
 79	 enemies = BotManager.Instance.GetEnemyBots(gameObject);
 80	 }
