 82	 /// <summary>
 83	 /// Инициализация отслеживания цели
 84	 /// </summary>
 85	 private void InitializeTargetTracking()
 86	 {
 87	 if (target != null)
 88	 {
 89	 lastTargetPosition = target.position;
 90	 lastValidTargetPosition = target.position;
 91	 hasValidTarget = true;
 92	
 93	 // Начальный путь к цели с использованием PathBerserker2d
 94	 if (navAgent.HasValidPosition)
 95	 {
 96	 navAgent.PathTo(target.position);
 97	 }
 98	 }
 99	 }
