 277	 /// <summary>
 278	 /// Обновление пути к цели с улучшенной логикой
 279	 /// </summary>
 280	 private void UpdatePathToTarget()
 281	 {
 282	 pathUpdateTimer = 0f;
 283	
 284	 if (!hasValidTarget) return;
 285	
 286	 Vector2 currentTargetPos = target.position;
 287	 Vector2 myPosition = transform.position;
 288	 float distanceToTarget = Vector2.Distance(myPosition, currentTargetPos);
 289	
 290	 // Предсказание движения цели
 291	 Vector2 predictedTargetPos = CalculatePredictedTargetPosition(currentTargetPos);
 292	
 293	 // Обновляем отслеживание позиции цели
 294	 UpdateTargetPositionTracking(currentTargetPos);
 295	
 296	 // Логика дистанции и остановки
 297	 if (HandleProximityLogic(distanceToTarget, predictedTargetPos))
 298	 {
 299	 return; // Обработка завершена в методе
 300	 }
 301	
 302	 // Обновление пути если не в режиме избегания
 303	 if (!IsInAvoidanceMode() && distanceToTarget > pathSettings.closeEnoughRadius)
 304	 {
 305	 RequestPathToTarget(predictedTargetPos);
 306	 }
 307	 }
