 309	 /// <summary>
 310	 /// Расчет предсказанной позиции цели
 311	 /// </summary>
 312	 private Vector2 CalculatePredictedTargetPosition(Vector2 currentPos)
 313	 {
 314	 if (pathSettings.targetPredictionTime <= 0f) return currentPos;
 315	
 316	 Vector2 targetVelocity = (currentPos - lastTargetPosition) / pathSettings.updateFrequency;
 317	
 318	 // Применяем предсказание только если цель движется достаточно быстро
 319	 if (targetVelocity.magnitude > 0.1f)
 320	 {
 321	 return currentPos + targetVelocity * pathSettings.targetPredictionTime;
 322	 }
 323	
 324	 return currentPos;
 325	 }
