 331	 {
 332	 lastTargetPosition = currentPos;
 333	
 334	 // Обновляем последнюю валидную позицию если агент может туда добраться
 335	 if (navAgent.HasValidPosition)
 336	 {
 337	 lastValidTargetPosition = currentPos;
 338	 }
