 341	 /// <summary>
 342	 /// Обработка логики близости к цели
 343	 /// </summary>
 344	 private bool HandleProximityLogic(float distance, Vector2 targetPos)
 345	 {
 346	 // Слишком близко - останавливаемся или отступаем
 347	 if (distance < pathSettings.travelStopRadius)
 348	 {
 349	 navAgent.Stop();
 350	
 351	 // Активное отступление при критической близости
 352	 if (distance < pathSettings.travelStopRadius * 0.7f)
 353	 {
 354	 ExecuteRetreatFromTarget(targetPos);
 355	 }
 356	 return true;
 357	 }
 358	
 359	 // Зона комфорта - не обновляем путь
 360	 if (distance >= pathSettings.travelStopRadius && distance <= pathSettings.closeEnoughRadius)
 361	 {
 362	 return true;
 363	 }
 364	
 365	 return false;
 366	 }
