 374	 Vector2 retreatPoint = targetPos + retreatDirection * (pathSettings.travelStopRadius * 1.2f);
 375	
 376	 if (navAgent.HasValidPosition)
 377	 {
 378	 navAgent.PathTo(retreatPoint);
 379	 }
