 522	 /// <summary>
 523	 /// Проверка блокирует ли союзник путь
 524	 /// </summary>
 525	 private bool IsAllyBlockingPath(GameObject ally, Vector2 myPosition, Vector2 pathDirection)
 526	 {
 527	 Vector2 allyPosition = ally.transform.position;
 528	 float distanceToAlly = Vector2.Distance(myPosition, allyPosition);
 529	
 530	 // Союзник слишком далеко
 531	 if (distanceToAlly > avoidanceSettings.allyDetectionDistance * 2f)
 532	 return false;
 533	
 534	 // Проекция союзника на путь
 535	 float projection = Vector2.Dot(allyPosition - myPosition, pathDirection);
 536	
 537	 // Союзник позади нас
 538	 if (projection <= 0) return false;
 539	
 540	 // Расстояние от союзника до линии пути
 541	 Vector2 projectedPoint = myPosition + pathDirection * projection;
 542	 float distanceFromPath = Vector2.Distance(allyPosition, projectedPoint);
 543	
 544	 return distanceFromPath < avoidanceSettings.allyDetectionDistance;
 545	 }
