 547	 /// <summary>
 548	 /// Расчет точки обхода препятствия
 549	 /// </summary>
 550	 private Vector2 CalculateAvoidancePoint(Vector2 obstaclePosition, bool isEnemy)
 551	 {
 552	 if (!hasValidTarget) return transform.position;
 553	
 554	 Vector2 myPosition = transform.position;
 555	 Vector2 targetPosition = target.position;
 556	 Vector2 directionToTarget = (targetPosition - myPosition).normalized;
 557	
 558	 // Выбираем дистанцию избегания в зависимости от типа препятствия
 559	 float avoidanceDistance = isEnemy ?
 560	 avoidanceSettings.enemyAvoidanceDistance :
 561	 avoidanceSettings.avoidanceOffset;
 562	
 563	 // Перпендикулярное направление для обхода
 564	 Vector2 perpendicularDirection = new Vector2(-directionToTarget.y, directionToTarget.x);
 565	
 566	 // Определяем сторону обхода
 567	 Vector2 toObstacle = obstaclePosition - myPosition;
 568	 if (Vector2.Dot(toObstacle, perpendicularDirection) < 0)
 569	 {
 570	 perpendicularDirection = -perpendicularDirection;
 571	 }
 572	
 573	 // Комбинируем направление к цели и перпендикулярное направление
 574	 Vector2 avoidanceDirection = (directionToTarget + perpendicularDirection).normalized;
 575	
 576	 // Рассчитываем точку обхода
 577	 Vector2 avoidancePoint = obstaclePosition + avoidanceDirection * avoidanceDistance;
 578	
 579	 // Для врагов добавляем дополнительное смещение от цели
 580	 if (isEnemy)
 581	 {
 582	 Vector2 awayFromTarget = (myPosition - targetPosition).normalized;
 583	 avoidancePoint += awayFromTarget * (avoidanceDistance * 0.3f);
 584	 }
 585	
 586	 return avoidancePoint;
 587	 }
